<?php

declare(strict_types=1);

namespace Database\Factories;

use App\Enums\ClassStatus;
use App\Models\PrivateClass;
use App\Models\User;
use Illuminate\Database\Eloquent\Factories\Factory;
use Illuminate\Support\Str;

/**
 * `join_code` is generated by the model's `creating` hook, so it is left unset.
 *
 * @extends Factory<PrivateClass>
 */
class PrivateClassFactory extends Factory
{
    /** @var class-string<PrivateClass> */
    protected $model = PrivateClass::class;

    /**
     * @return array<string, mixed>
     */
    public function definition(): array
    {
        return [
            'instructor_id' => User::factory()->instructor(),
            'name' => Str::title($this->faker->unique()->words(3, true)).' Cohort',
            'description' => $this->faker->sentence(14),
            'max_students' => 50,
            'status' => ClassStatus::Active,
        ];
    }

    public function forInstructor(?User $instructor = null): static
    {
        return $this->state(fn (array $attributes): array => [
            'instructor_id' => $instructor?->getKey() ?? User::factory()->instructor(),
        ]);
    }

    public function archived(): static
    {
        return $this->state(fn (array $attributes): array => [
            'status' => ClassStatus::Archived,
        ]);
    }

    public function full(): static
    {
        return $this->state(fn (array $attributes): array => [
            'max_students' => 1,
        ]);
    }
}
